Here are the two functions to pack and unpack the data.

### The Logic

1.  **Packing**: We iterate through the entities. For each entity, we take the `id` (4 bits) and `size` (3 bits), concatenate them into a 7-bit integer, and write that integer into the `Uint8Array` at the current offset. We then advance the offset by 1 byte (8 bits).
2.  **Unpacking**: We iterate through the `Uint8Array`. For each byte, we extract the lower 4 bits as the `id` and the upper 3 bits as the `size`.

### The Code

```javascript
/**
 * Packs an array of entities into a Uint8Array (ArrayBuffer).
 * 
 * @param {Array} entities - Array of objects with { id: number, size: number }
 * @returns {Uint8Array} - The packed buffer
 */
function packEntities(entities) {
  if (!Array.isArray(entities)) {
    throw new Error("Input must be an array of entities");
  }

  // Calculate total size: 1 byte per entity (4 bits + 3 bits = 7 bits < 8 bits)
  const bufferSize = entities.length;
  const buffer = new Uint8Array(bufferSize);
  let offset = 0;

  for (const entity of entities) {
    // Validate input
    if (typeof entity.id !== 'number' || typeof entity.size !== 'number') {
      throw new Error("Entity must have numeric 'id' and 'size' fields");
    }

    // Masking logic:
    // 1. Extract ID (4 bits): id & 0xF (binary 1111)
    // 2. Extract Size (3 bits): size & 0x7 (binary 0111)
    // 3. Shift size to the upper 3 bits: (size << 4)
    // 4. Combine: (size << 4) | id
    const packedValue = ((entity.size & 0x7) << 4) | (entity.id & 0xF);

    buffer[offset] = packedValue;
    offset++;
  }

  return buffer;
}

/**
 * Unpacks a Uint8Array back into an array of entities.
 * 
 * @param {Uint8Array} buffer - The packed buffer
 * @returns {Array} - Array of objects with { id: number, size: number }
 */
function unpackEntities(buffer) {
  if (!(buffer instanceof Uint8Array)) {
    throw new Error("Input must be a Uint8Array");
  }

  const entities = [];
  // Iterate through the buffer. Since each entity is exactly 1 byte,
  // we can simply loop through the length of the buffer.
  for (let i = 0; i < buffer.length; i++) {
    const byte = buffer[i];

    // Extract ID (lower 4 bits): byte & 0xF
    const id = byte & 0xF;

    // Extract Size (upper 3 bits): (byte >> 4) & 0x7
    const size = (byte >> 4) & 0x7;

    entities.push({ id, size });
  }

  return entities;
}

