import { parse } from 'csv-parse/sync';

// We use a simple self-posting pattern to communicate back to the main thread
// without needing a complex message passing setup.

self.onmessage = function(e) {
  const { fileContent, delimiter } = e.data;

  try {
    // Parse the CSV string
    const records = parse(fileContent, {
      delimiter: delimiter || ',',
      skip_empty_lines: true,
      columns: true, // Automatically generate headers from the first row
      trim: true
    });

    // Send the result back to the main thread
    self.postMessage({
      type: 'success',
      data: records
    });
  } catch (error) {
    self.postMessage({
      type: 'error',
      message: error.message
    });
  }
};
